import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import roomService from '../../services/roomService';
import PageHeader from '../../components/common/PageHeader';
import '../../components/common/shared.css';
import './RoomsPage.css';

const TYPE_LABELS = {
  SIMPLE: 'Simple',
  DOUBLE: 'Double',
  SUITE:  'Suite',
  DELUXE: 'Deluxe',
  // minuscule pour compatibilité avec les anciennes réponses
  single: 'Simple',
  double: 'Double',
  suite:  'Suite',
  deluxe: 'Deluxe',
};

const RoomsPage = () => {
  const navigate = useNavigate();
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ check_in: '', check_out: '', type: '' });

  const fetchRooms = () => {
    setLoading(true);
    const params = {};
    if (filters.check_in)  params.checkIn  = filters.check_in;
    if (filters.check_out) params.checkOut = filters.check_out;
    if (filters.type)      params.type     = filters.type;

    roomService.getAvailable(params)
      .then(setRooms)
      .catch(() => roomService.getAll(params).then(setRooms))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchRooms(); }, []); // eslint-disable-line

  const handleFilter = (e) => {
    e.preventDefault();
    fetchRooms();
  };

  return (
    <div>
      <PageHeader
        title="Chambres disponibles"
        subtitle="Choisissez votre chambre et réservez en quelques clics"
      />

      {/* Filter bar */}
      <form className="rooms-filter" onSubmit={handleFilter}>
        <div className="form-group">
          <label className="form-label">Arrivée</label>
          <input
            type="date"
            className="form-input"
            value={filters.check_in}
            min={new Date().toISOString().split('T')[0]}
            onChange={e => setFilters(p => ({ ...p, check_in: e.target.value }))}
          />
        </div>
        <div className="form-group">
          <label className="form-label">Départ</label>
          <input
            type="date"
            className="form-input"
            value={filters.check_out}
            min={filters.check_in || new Date().toISOString().split('T')[0]}
            onChange={e => setFilters(p => ({ ...p, check_out: e.target.value }))}
          />
        </div>
        <div className="form-group">
          <label className="form-label">Type</label>
          <select
            className="form-select"
            value={filters.type}
            onChange={e => setFilters(p => ({ ...p, type: e.target.value }))}
          >
            <option value="">Tous les types</option>
            <option value="SIMPLE">Simple</option>
            <option value="DOUBLE">Double</option>
            <option value="SUITE">Suite</option>
            <option value="DELUXE">Deluxe</option>
          </select>
        </div>
        <button type="submit" className="btn btn--gold rooms-filter__btn">
          Rechercher
        </button>
      </form>

      {loading ? (
        <div className="rooms-loading">
          <span className="dt-spinner" style={{width:24, height:24}} />
          Chargement des chambres…
        </div>
      ) : rooms.length === 0 ? (
        <div className="rooms-empty">
          Aucune chambre disponible pour ces dates.
        </div>
      ) : (
        <div className="rooms-grid">
          {rooms.map(room => (
            <div key={room.id} className="room-card">
              {/*
                CORRECTION #1 : suppression de "Chambre {room.number}".
                Le client voit uniquement le type et la description — jamais le numéro physique.
              */}
              <div className="room-card__header">
                <span className="room-card__type">{TYPE_LABELS[room.type] ?? room.type}</span>
                <span className="room-card__capacity">
                  {room.capacity ? `${room.capacity} pers. max` : ''}
                </span>
              </div>
              <div className="room-card__body">
                <p className="room-card__desc">
                  {room.description || 'Chambre confortable avec tout le nécessaire.'}
                </p>
                <div className="room-card__amenities">
                  {(room.amenities ?? ['WiFi', 'Climatisation', 'TV']).map((a, i) => (
                    <span key={i} className="room-card__amenity">{a}</span>
                  ))}
                </div>
              </div>
              <div className="room-card__footer">
                <div>
                  <p className="room-card__price">{room.price_per_night ?? room.price} €</p>
                  <p className="room-card__per">/ nuit</p>
                </div>
                <button
                  className="btn btn--gold"
                  onClick={() => navigate('/client/book', {
                    state: { room, checkIn: filters.check_in, checkOut: filters.check_out }
                  })}
                >
                  Réserver
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default RoomsPage;
